<?php

declare(strict_types=1);

if (!function_exists('response_error')) {
	require_once dirname(__DIR__, 3) . '/bootstrap.php';
}
require_once dirname(__DIR__, 3) . '/services/RazorpayService.php';

if (($_SERVER['REQUEST_METHOD'] ?? '') !== 'GET') {
	response_error('METHOD_NOT_ALLOWED', 'Method not allowed.', 405);
}

$token = is_string($_GET['token'] ?? null) ? $_GET['token'] : '';
$claims = RazorpayService::verifyCheckoutToken($token);
if ($claims === null) {
	response_error('INVALID_CHECKOUT_TOKEN', 'This checkout link is invalid or expired.', 400);
}

$database = database_connection();
$statement = $database->prepare(
	"SELECT s.provider_subscription_id, p.code, p.name, p.price, p.currency
	 FROM subscriptions s INNER JOIN subscription_plans p ON p.id = s.plan_id
	 WHERE s.id = :id AND s.user_id = :user_id AND s.provider = 'razorpay'
	 AND s.status = 'pending' LIMIT 1"
);
$statement->execute(['id' => $claims['subscription_id'], 'user_id' => $claims['user_id']]);
$subscription = $statement->fetch();
if (!$subscription) {
	response_error('CHECKOUT_NOT_AVAILABLE', 'This subscription checkout is no longer available.', 409);
}

$keyId = htmlspecialchars(RazorpayService::keyId(), ENT_QUOTES, 'UTF-8');
$providerSubscriptionId = htmlspecialchars($subscription['provider_subscription_id'], ENT_QUOTES, 'UTF-8');
$completeUrl = htmlspecialchars('/health-app/backend/api/v1/subscription/checkout/complete', ENT_QUOTES, 'UTF-8');
$planName = htmlspecialchars($subscription['name'], ENT_QUOTES, 'UTF-8');
$planNameJson = json_encode($subscription['name'], JSON_THROW_ON_ERROR);
$planPrice = (float) $subscription['price'];
$planCurrency = htmlspecialchars($subscription['currency'], ENT_QUOTES, 'UTF-8');

header('Content-Type: text/html; charset=utf-8');
echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f5faf7"><title>Subscription payment</title><style>';
echo ':root{color-scheme:light;--ink:#16332a;--muted:#6d7f78;--line:#e2ebe6;--surface:#fff;--canvas:#f5faf7;--green:#16845b;--green-soft:#e8f6ef;--amber:#b86b12;--amber-soft:#fff4df;--red:#c44747;--red-soft:#fff0f0;--shadow:0 18px 50px rgba(27,76,56,.12)}*{box-sizing:border-box}body{margin:0;min-width:320px;background:radial-gradient(circle at 50% -10%,#fff 0,#f5faf7 48%,#edf6f0 100%);color:var(--ink);font-family:ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;line-height:1.5}main{min-height:100vh;display:flex;align-items:center;justify-content:center;padding:28px 16px}.shell{width:min(100%,460px);animation:rise .45s ease-out both}.brand{display:flex;align-items:center;gap:10px;margin:0 auto 18px;width:max-content;color:var(--green);font-size:13px;font-weight:750;letter-spacing:.04em}.brand-mark{display:grid;place-items:center;width:28px;height:28px;border-radius:9px;background:var(--green);color:#fff;font-size:15px}.card{background:var(--surface);border:1px solid rgba(226,235,230,.9);border-radius:24px;box-shadow:var(--shadow);padding:32px 24px 26px;text-align:center}.status-icon{width:72px;height:72px;margin:0 auto 20px;border-radius:50%;display:grid;place-items:center;font-size:34px;font-weight:700;line-height:1;animation:pop .4s .1s ease-out both}.status-icon.success{background:var(--green-soft);color:var(--green)}.status-icon.pending{background:var(--amber-soft);color:var(--amber)}.status-icon.error{background:var(--red-soft);color:var(--red)}.status-icon.loading{background:#edf4f0;color:var(--green);font-size:22px}.status-icon.loading:after{content:"";width:24px;height:24px;border:3px solid #cce5d8;border-top-color:var(--green);border-radius:50%;animation:spin .8s linear infinite}h1{margin:0;font-size:27px;letter-spacing:-.02em;line-height:1.15}#message{margin:12px auto 0;max-width:34ch;color:var(--muted);font-size:15px}.summary{margin:26px 0 22px;padding:16px;border:1px solid var(--line);border-radius:16px;background:#fbfdfc;text-align:left}.summary-title{margin:0 0 12px;color:var(--muted);font-size:11px;font-weight:800;letter-spacing:.1em;text-transform:uppercase}.detail{display:flex;align-items:baseline;justify-content:space-between;gap:18px;padding:9px 0;border-bottom:1px solid var(--line);font-size:14px}.detail:last-child{border-bottom:0;padding-bottom:0}.detail:first-of-type{padding-top:0}.detail-label{color:var(--muted)}.detail-value{max-width:65%;overflow-wrap:anywhere;text-align:right;font-weight:700}.detail-value.payment-id{font-size:12px}.action{display:inline-flex;align-items:center;justify-content:center;min-height:48px;width:100%;border:0;border-radius:13px;background:var(--green);color:#fff;cursor:pointer;font:inherit;font-weight:750;box-shadow:0 8px 18px rgba(22,132,91,.2);transition:transform .2s ease,background .2s ease}.action:hover{background:#106d4b;transform:translateY(-1px)}.note{margin:18px auto 0;max-width:35ch;color:var(--muted);font-size:13px}.footer{padding:18px 0 0;text-align:center;color:#84958e;font-size:12px;font-weight:650}@keyframes rise{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}@keyframes pop{from{opacity:0;transform:scale(.78)}to{opacity:1;transform:scale(1)}}@keyframes spin{to{transform:rotate(360deg)}}@media (min-width:480px){main{padding:40px 24px}.card{padding:40px 36px 30px}}@media (prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}}</style></head><body><main><div class="shell"><div class="brand"><span class="brand-mark">+</span><span>AI Health &amp; Wellness</span></div><section class="card" aria-live="polite"><div id="status-icon" class="status-icon loading" aria-hidden="true"></div><h1 id="title">Opening secure checkout</h1><p id="message">Please wait while Razorpay Checkout opens.</p><div id="summary" class="summary" hidden><p class="summary-title">Subscription summary</p><div class="detail"><span class="detail-label">Plan</span><span id="plan-value" class="detail-value">' . $planName . '</span></div><div class="detail"><span class="detail-label">Amount</span><span id="amount-value" class="detail-value">' . htmlspecialchars(number_format($planPrice, 2), ENT_QUOTES, 'UTF-8') . ' ' . $planCurrency . '</span></div><div id="payment-row" class="detail" hidden><span class="detail-label">Payment ID</span><span id="payment-value" class="detail-value payment-id"></span></div></div><button id="return-button" class="action" type="button" hidden>Return to App</button><p id="note" class="note" hidden>You can safely close this page and return to the Health &amp; Wellness app.</p></section><footer class="footer">AI Health &amp; Wellness</footer></div></main>';
echo '<script src="https://checkout.razorpay.com/v1/checkout.js"></script>';
echo '<script>var icon=document.getElementById("status-icon");var title=document.getElementById("title");var message=document.getElementById("message");var summary=document.getElementById("summary");var paymentRow=document.getElementById("payment-row");var paymentValue=document.getElementById("payment-value");var returnButton=document.getElementById("return-button");var note=document.getElementById("note");var planName=' . $planNameJson . ';function setResult(state,heading,copy){icon.className="status-icon "+state;icon.textContent=state==="success"?"✓":state==="pending"?"!":"×";title.textContent=heading;message.textContent=copy;summary.hidden=false;returnButton.hidden=false;note.hidden=false}returnButton.addEventListener("click",function(){window.close()});var options={key:' . json_encode($keyId, JSON_THROW_ON_ERROR) . ',subscription_id:' . json_encode($providerSubscriptionId, JSON_THROW_ON_ERROR) . ',name:"AI Health & Wellness",description:' . json_encode($subscription['name'], JSON_THROW_ON_ERROR) . ',handler:function(response){icon.className="status-icon loading";icon.textContent="";title.textContent="Confirming your payment";message.textContent="Your payment was received. We are confirming your membership activation.";fetch(' . json_encode($completeUrl, JSON_THROW_ON_ERROR) . ',{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({token:' . json_encode($token, JSON_THROW_ON_ERROR) . ',razorpay_payment_id:response.razorpay_payment_id,razorpay_subscription_id:response.razorpay_subscription_id,razorpay_signature:response.razorpay_signature})}).then(function(result){return result.json()}).then(function(result){if(result.success&&result.data&&result.data.status==="pending"){setResult("pending","Payment Received","Payment received. Your membership activation is being confirmed.");return}if(result.success&&result.data&&result.data.status==="verified"){paymentRow.hidden=false;paymentValue.textContent=response.razorpay_payment_id;setResult("success","Payment Successful","Your subscription payment was received successfully.");message.textContent="Your "+planName+" membership is now active.";return}setResult("error","Payment Verification Failed","We could not confirm your subscription payment. Please return to the app and try again.")}).catch(function(){setResult("error","Payment Verification Failed","We could not confirm your subscription payment. Please return to the app and try again.")})},modal:{ondismiss:function(){icon.className="status-icon error";icon.textContent="×";title.textContent="Checkout closed";message.textContent="No subscription was activated. You can safely close this page and return to the app.";summary.hidden=true;note.hidden=true}}};new Razorpay(options).open();</script></body></html>';
exit;